// IOT - Publicacion de Telemetria de Sensor por MQTT en C Embebido
#include <stdio.h>
typedef struct {
    float temperature_c;
    float humidity_pct;
    uint16_t battery_mv;
} SensorPayload;
void serialize_payload(const SensorPayload *data, char *buffer) {
    sprintf(buffer, "{\"t\":%.1f,\"h\":%.1f,\"v\":%u}", data->temperature_c, data->humidity_pct, data->battery_mv);
}

